import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"佳景留心惯","description":"","frontmatter":{"title":"佳景留心惯","date":"2026-11-20T00:00:00.000Z","seq":121,"categories":["美文","全宋词"],"collection":"《全宋词 · 柳永》","tags":["全宋词","宋"],"poem":true,"poem_quote":false,"author":"柳永","source_book":"全宋词"},"headers":[],"relativePath":"blogs/全宋词·柳永/佳景留心惯.md","filePath":"blogs/全宋词·柳永/佳景留心惯.md"}'),o={name:"blogs/全宋词·柳永/佳景留心惯.md"};function l(c,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="佳景留心惯" tabindex="-1">佳景留心惯 <a class="header-anchor" href="#佳景留心惯" aria-label="Permalink to &quot;佳景留心惯&quot;">​</a></h1><p class="poem-meta">宋 · 柳永　·　洞仙歌</p><div class="poem"><p class="poem-stanza">佳景留心惯。</p><p class="poem-stanza">况少年彼此，风情非浅。</p><p class="poem-stanza">有笙歌巷陌，绮罗庭院。</p><p class="poem-stanza">倾城巧笑如花面。</p><p class="poem-stanza">恣雅态、明眸回美盼。</p><p class="poem-stanza">同心绾。</p><p class="poem-stanza">算国艳仙材，翻恨相逢晚。</p><p class="poem-stanza">缱绻。</p><p class="poem-stanza">洞房悄悄，绣被重重，夜永欢馀，共有海约山盟，记得翠云偷翦。</p><p class="poem-stanza">和鸣彩凤于飞燕。</p><p class="poem-stanza">间柳径花阴携手遍。</p><p class="poem-stanza">情眷恋。</p><p class="poem-stanza">向其间、密约轻怜事何限。</p><p class="poem-stanza">忍聚散。</p><p class="poem-stanza">况已结深深愿。</p><p class="poem-stanza">愿人间天上，暮云朝雨长相见。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
